<?php
declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';
$page=$_GET['page']??'home';$error='';$notice=$_SESSION['flash']??null;unset($_SESSION['flash']);$user=$_SESSION['user']??null;$stats=[];$reports=[];$comments=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();$action=$_POST['action']??'';
 try{
  if($action==='register'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$pw=$_POST['password']??'';if($name===''||mb_strlen($name)>100)throw new RuntimeException('Enter a name up to 100 characters.');if(!valid_email($email))throw new RuntimeException('Enter a valid email address.');if(!valid_phone($phone))throw new RuntimeException('Phone number must contain exactly 10 digits.');if(!valid_password($pw))throw new RuntimeException('Password must be at least 8 characters and include uppercase, lowercase, and a number.');$q=db()->prepare('INSERT INTO users(name,email,phone,password_hash) VALUES(?,?,?,?)');$q->execute([$name,$email,$phone,password_hash($pw,PASSWORD_DEFAULT)]);flash('Account created. You can now sign in.');redirect('/?page=login');}
  if($action==='login'){$email=trim($_POST['email']??'');$pw=$_POST['password']??'';$q=db()->prepare('SELECT id,name,email,password_hash,role FROM users WHERE email=?');$q->execute([$email]);$u=$q->fetch();if(!$u||!password_verify($pw,$u['password_hash']))throw new RuntimeException('Email or password is incorrect.');session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];flash('Welcome, '.$u['name'].'.');redirect('/');}
  if($action==='admin_login'){$email=trim($_POST['email']??'');$pw=$_POST['password']??'';$envEmail=env_value('ADMIN_EMAIL','admin@example.com');$envPw=env_value('ADMIN_PASSWORD','ChangeMe123!');if(!hash_equals($envEmail,$email)||!hash_equals($envPw,$pw))throw new RuntimeException('Email or password is incorrect.');session_regenerate_id(true);$_SESSION['user']=['id'=>0,'name'=>'Administrator','email'=>$email,'role'=>'admin'];flash('Administrator signed in.');redirect('/?page=admin');}
  if($action==='logout'){$_SESSION=[];session_destroy();redirect('/');}
  if($action==='book_test'){require_login();$slot=$_POST['slot_date']??'';if(!valid_slot_date($slot))throw new RuntimeException('Choose a valid test date starting tomorrow.');$q=db()->prepare('INSERT INTO appointments(user_id,slot_date) VALUES(?,?)');$q->execute([$_SESSION['user']['id'],$slot]);flash('Test slot request submitted.');redirect('/?page=search');}
  if($action==='comment'){require_login();$body=trim($_POST['body']??'');if($body===''||mb_strlen($body)>1000)throw new RuntimeException('Comment must be between 1 and 1000 characters.');$q=db()->prepare('INSERT INTO comments(user_id,body) VALUES(?,?)');$q->execute([$_SESSION['user']['id'],$body]);flash('Your comment was posted.');redirect('/#community');}
 }catch(Throwable $e){$error=$e instanceof PDOException&&str_contains($e->getMessage(),'23000')?'An account with that email already exists.':$e->getMessage();}
}
try{if(in_array($page,['home','dashboard'],true))$stats=db()->query('SELECT state_name,tests_done FROM state_stats ORDER BY tests_done DESC')->fetchAll();if($page==='home')$comments=db()->query('SELECT c.body,c.created_at,u.name FROM comments c JOIN users u ON u.id=c.user_id ORDER BY c.created_at DESC LIMIT 8')->fetchAll();if($page==='search'&&isset($_GET['q'])&&!empty($user)){$q=trim($_GET['q']);if($q!==''){$s=db()->prepare('SELECT order_number,patient_name,mobile,test_date,result FROM test_reports WHERE order_number=? OR mobile=? OR patient_name LIKE ? ORDER BY test_date DESC LIMIT 20');$s->execute([$q,$q,'%'.$q.'%']);$reports=$s->fetchAll();}}if($page==='admin'){require_admin();$reports=db()->query('SELECT order_number,patient_name,mobile,test_date,result FROM test_reports ORDER BY test_date DESC LIMIT 50')->fetchAll();}}catch(Throwable $e){$error=$e instanceof PDOException?'Database unavailable. Configure MySQL and import database/schema.sql.':$e->getMessage();}
if($page==='download'){require_login();$s=db()->prepare('SELECT order_number,patient_name,mobile,test_date,result FROM test_reports WHERE order_number=?');$s->execute([trim($_GET['order']??'')]);$r=$s->fetch();if(!$r){http_response_code(404);$page='not-found';}else{header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.preg_replace('/[^A-Za-z0-9_-]/','_',$r['order_number']).'.csv"');$f=fopen('php://output','w');fputcsv($f,['Order number','Patient','Mobile','Test date','Result']);fputcsv($f,array_values($r));fclose($f);exit;}}
function formtoken():void{echo '<input type="hidden" name="_csrf" value="'.h(csrf_token()).'">';}
function startpage(string $title):void{global $notice,$error,$user;?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> · CovidCare</title><link rel="stylesheet" href="/assets/styles.css"></head><body><header><a class="brand" href="/">✚ CovidCare</a><nav><a href="/#updates">Updates</a><a href="/?page=dashboard">Dashboard</a><a href="/?page=search">Search report</a><?php if($user):?><span><?=h($user['name'])?></span><?php if($user['role']==='admin'):?><a href="/?page=admin">Admin</a><?php endif?><form method="post" class="inline"><?php formtoken()?><input type="hidden" name="action" value="logout"><button class="textbutton">Sign out</button></form><?php else:?><a href="/?page=login">Sign in</a><a class="navbutton" href="/?page=register">Create account</a><?php endif?></nav></header><main><?php if($notice):?><div class="notice"><?=h($notice[0])?></div><?php endif?><?php if($error!==''):?><div class="notice error" role="alert"><?=h($error)?></div><?php endif?><?php }
function endpage():void{?></main><footer>CovidCare · STQA learning project <span>Demonstration information only; consult local health authorities.</span></footer></body></html><?php }
startpage(ucfirst($page));
if($page==='register'||$page==='login'||$page==='admin-login'){$register=$page==='register';?><section class="form"><p class="eyebrow"><?=$register?'JOIN THE COMMUNITY':'WELCOME BACK'?></p><h1><?=$register?'Create your account':($page==='admin-login'?'Administrator sign in':'Sign in')?></h1><form method="post"><?php formtoken()?><input type="hidden" name="action" value="<?=$register?'register':($page==='admin-login'?'admin_login':'login')?>"><?php if($register):?><label>Full name<input name="name" required maxlength="100" autocomplete="name"></label><?php endif?><label>Email address<input name="email" type="email" required maxlength="254" autocomplete="username"></label><?php if($register):?><label>10-digit mobile number<input name="phone" required inputmode="numeric" pattern="[0-9]{10}" maxlength="10"><small>Digits only, no country code.</small></label><?php endif?><label>Password<input name="password" type="password" required <?=$register?'minlength="8" autocomplete="new-password"':'autocomplete="current-password"'?>></label><?php if($register):?><small>At least 8 characters with uppercase, lowercase, and a number.</small><?php endif?><button class="button"><?=$register?'Create account':'Sign in'?></button></form><?php if($register):?><p>Already registered? <a href="/?page=login">Sign in</a></p><?php else:?><p>New here? <a href="/?page=register">Create an account</a></p><a href="/?page=admin-login">Administrator access</a><?php endif?></section><?php }
elseif($page==='dashboard'){?><section class="heading"><p class="eyebrow">PUBLIC HEALTH SNAPSHOT</p><h1>Testing dashboard</h1><p>Sample statewise totals for demonstrating the dashboard and its tests.</p></section><section class="grid"><?php foreach($stats as $s):?><article class="card"><span><?=h($s['state_name'])?></span><strong><?=number_format((int)$s['tests_done'])?></strong><small>tests recorded</small></article><?php endforeach?></section><p class="muted">Seeded demonstration data, not a live public health feed.</p><?php }
elseif($page==='search'){?><section class="heading"><p class="eyebrow">TESTING SERVICES</p><h1>Find a test report</h1><p>Search by patient name, 10-digit mobile number, or order number.</p></section><?php if(!$user):?><p>Sign in to search reports. <a href="/?page=login">Sign in</a></p><?php else:?><form class="search" method="get"><input type="hidden" name="page" value="search"><label class="sr-only" for="q">Search reports</label><input id="q" name="q" value="<?=h($_GET['q']??'')?>" placeholder="Name, mobile, or order number"><button class="button">Search</button></form><form class="slot" method="post"><?php formtoken()?><input type="hidden" name="action" value="book_test"><label>Request a test slot (available from tomorrow)<input type="date" name="slot_date" min="<?=h((new DateTimeImmutable('tomorrow'))->format('Y-m-d'))?>" required></label><button class="button">Request slot</button></form><?php if(isset($_GET['q'])):if($reports):?><div class="tablewrap"><table><thead><tr><th>Order</th><th>Patient</th><th>Test date</th><th>Result</th><th></th></tr></thead><tbody><?php foreach($reports as $r):?><tr><td><?=h($r['order_number'])?></td><td><?=h($r['patient_name'])?></td><td><?=h($r['test_date'])?></td><td><?=h($r['result'])?></td><td><a href="/?page=download&amp;order=<?=rawurlencode($r['order_number'])?>">Download</a></td></tr><?php endforeach?></tbody></table></div><?php else:?><p class="muted">No matching reports found.</p><?php endif;endif;endif;}
elseif($page==='not-found'){?><h1>Report not found</h1><?php }
elseif($page==='admin'){?><section class="heading"><p class="eyebrow">ADMINISTRATION</p><h1>Testing reports</h1></section><div class="tablewrap"><table><thead><tr><th>Order</th><th>Patient</th><th>Mobile</th><th>Date</th><th>Result</th></tr></thead><tbody><?php foreach($reports as $r):?><tr><?php foreach($r as $v):?><td><?=h((string)$v)?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div><?php }
else{?><section class="hero" id="updates"><div><p class="eyebrow">INFORMATION · TESTING · COMMUNITY</p><h1>Clear information helps us care for each other.</h1><p>Find prevention guidance, explore sample testing updates, and access your COVID-19 test report.</p><a class="button" href="/?page=dashboard">Explore the dashboard</a></div><div class="orb" aria-hidden="true">✚</div></section><section class="grid two"><article class="panel"><p class="eyebrow">STAY INFORMED</p><h2>Everyday prevention</h2><ul><li>Stay up to date with recommended vaccinations.</li><li>Improve indoor ventilation; consider a mask in crowded spaces.</li><li>Stay home when unwell and follow local health guidance.</li><li>Wash hands regularly and cover coughs and sneezes.</li></ul></article><article class="panel"><p class="eyebrow">STATEWISE OVERVIEW</p><h2>Testing snapshot</h2><?php foreach(array_slice($stats,0,3) as $s):?><p class="row"><?=h($s['state_name'])?><strong><?=number_format((int)$s['tests_done'])?></strong></p><?php endforeach?><a href="/?page=dashboard">View all states →</a></article></section><section class="grid two community" id="community"><article><p class="eyebrow">COMMUNITY</p><h2>Questions and feedback</h2><?php if($user):?><form method="post"><?php formtoken()?><input type="hidden" name="action" value="comment"><label class="sr-only" for="body">Your comment</label><textarea id="body" name="body" maxlength="1000" required></textarea><button class="button">Post comment</button></form><?php else:?><a href="/?page=login">Sign in to comment</a><?php endif?></article><article><?php foreach($comments as $c):?><div class="comment"><strong><?=h($c['name'])?></strong><small><?=h($c['created_at'])?></small><p><?=nl2br(h($c['body']))?></p></div><?php endforeach?></article></section><?php }
endpage();
